// Hand-written code and tests stay at or under 800 lines (CONTRIBUTING.md): a file that size has one
// job, fits in a review and in an agent's context. Generated files are exempt; they say so in their
// header. Documentation has no hard limit, but is split by topic.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, it } from 'node:test';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const MAX_LINES = 800;
const CODE = /\.(ts|tsx|js|mjs|cjs|rs|swift|kt|kts|sh)$/;
const GENERATED = /autogenerated|@generated|do not edit/i;

export const isGenerated = (text) => GENERATED.test(text.split('\n', 5).join('\n'));

/** Hand-written code files over the limit, as `path: lines`. */
export function oversized(files) {
  return files
    .filter(({ path, text }) => CODE.test(path) && !isGenerated(text))
    .map(({ path, text }) => ({
      path,
      lines: text.split('\n').length - (text.endsWith('\n') ? 1 : 0),
    }))
    .filter(({ lines }) => lines > MAX_LINES)
    .map(({ path, lines }) => `${path}: ${lines} lines`);
}

describe(`code files stay at or under ${MAX_LINES} lines`, () => {
  it('counts code, skips generated files and documentation', () => {
    const long = 'x\n'.repeat(MAX_LINES + 1);
    assert.deepEqual(
      oversized([
        { path: 'a.ts', text: long },
        { path: 'ok.rs', text: 'x\n'.repeat(MAX_LINES) },
        { path: 'b.kt', text: `// This file was autogenerated by uniffi.\n${long}` },
        {
          path: 'c.ts',
          text: `/**\n * @generated by tran-tokens-codegen — do not edit by hand.\n */\n${long}`,
        },
        { path: 'README.md', text: long },
      ]),
      [`a.ts: ${MAX_LINES + 1} lines`]
    );
  });

  it('holds for every file in the working tree', () => {
    const paths = execFileSync(
      'git',
      ['ls-files', '-z', '--cached', '--others', '--exclude-standard'],
      {
        cwd: ROOT,
        encoding: 'utf8',
      }
    )
      .split('\0')
      .filter((path) => CODE.test(path) && existsSync(join(ROOT, path)));
    const files = paths.map((path) => ({ path, text: readFileSync(join(ROOT, path), 'utf8') }));
    assert.deepEqual(oversized(files), []);
  });
});
